from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix_steps(n: int) -> int:
            if n <= 0:
                return 0

            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0

        for l, r in queries:
            total_single_number_steps = prefix_steps(r) - prefix_steps(l - 1)
            answer += (total_single_number_steps + 1) // 2

        return answer
